QB.push(
{id:"l65",d:"lgpd",t:"ce",e:"Cebraspe",q:"O controlador deve informar imediatamente aos agentes com os quais tenha compartilhado dados a correção, a eliminação, a anonimização ou o bloqueio desses dados, para que repitam o procedimento, salvo impossibilidade ou esforço desproporcional.",a:true,c:"Dever de propagação das correções.",r:"LGPD, art. 18, §6º"},
{id:"l66",d:"lgpd",t:"ce",e:"Cebraspe",q:"Os dados referentes ao exercício regular de direitos pelo titular podem ser utilizados em seu prejuízo, desde que haja previsão contratual.",a:false,c:"Não podem ser usados em prejuízo do titular.",r:"LGPD, art. 21"},
{id:"l67",d:"lgpd",t:"ce",e:"Cebraspe",q:"A defesa dos interesses e dos direitos dos titulares de dados pode ser exercida em juízo, individual ou coletivamente.",a:true,c:"Remete à legislação sobre tutela individual e coletiva.",r:"LGPD, art. 22"},
{id:"l68",d:"lgpd",t:"ce",e:"Cebraspe",q:"Os dados pessoais devem ser armazenados em formato que favoreça o exercício do direito de acesso.",a:true,c:"Facilita o atendimento ao titular.",r:"LGPD, art. 19, §1º"},
{id:"l69",d:"lgpd",t:"ce",e:"Cebraspe",q:"Os dados no âmbito do Poder Público devem ser mantidos em formato interoperável e estruturado para o uso compartilhado, visando à execução de políticas públicas e à disseminação de informações ao público.",a:true,c:"Interoperabilidade no setor público.",r:"LGPD, art. 25"},
{id:"l70",d:"lgpd",t:"ce",e:"Cebraspe",q:"A ANPD pode dispor sobre padrões técnicos mínimos para tornar aplicáveis as medidas de segurança previstas na LGPD.",a:true,c:"Considerando a natureza das informações, as características do tratamento e o estado atual da tecnologia.",r:"LGPD, art. 46, §1º"},
{id:"l71",d:"lgpd",t:"ce",e:"Cebraspe",q:"Os sistemas utilizados para o tratamento de dados devem ser estruturados de forma a atender aos requisitos de segurança, aos padrões de boas práticas e de governança e aos princípios gerais da LGPD.",a:true,c:"Literalidade do art. 49.",r:"LGPD, art. 49"},
{id:"l72",d:"lgpd",t:"me",e:"FGV",q:"Segundo a LGPD, um programa de governança em privacidade deve, no mínimo, entre outros requisitos:",o:["ser aplicável apenas aos dados sensíveis.","dispensar planos de resposta a incidentes quando houver seguro.","contar com planos de resposta a incidentes e remediação e ser atualizado com base em monitoramento contínuo e avaliações periódicas.","ser aprovado previamente pela ANPD para ter validade.","limitar-se aos dados tratados em meios físicos."],a:2,c:"O art. 50, §2º, I, lista requisitos mínimos, entre eles resposta a incidentes e monitoramento contínuo.",r:"LGPD, art. 50, §2º"},
{id:"l73",d:"lgpd",t:"ce",e:"Cebraspe",q:"As metodologias que orientam o cálculo do valor-base das multas devem ser objeto de regulamentação própria da ANPD, precedida de consulta pública.",a:true,c:"Concretizado pela Res. CD/ANPD 4/2023.",r:"LGPD, art. 53"},
{id:"l74",d:"lgpd",t:"ce",e:"Cebraspe",q:"A adoção de política de boas práticas e governança é parâmetro considerado na aplicação das sanções administrativas.",a:true,c:"Atenua a sanção.",r:"LGPD, art. 52, §1º, IX"},
{id:"l75",d:"lgpd",t:"ce",e:"Cebraspe",q:"Pessoas jurídicas de direito público podem requerer à ANPD a avaliação do nível de proteção de dados de país ou organismo internacional.",a:true,c:"Previsão do parágrafo único do art. 33.",r:"LGPD, art. 33, parágrafo único"},
{id:"l76",d:"lgpd",t:"ce",e:"Cebraspe",q:"Os controladores que tratam dados de crianças devem manter pública a informação sobre os tipos de dados coletados, a forma de sua utilização e os procedimentos para o exercício dos direitos.",a:true,c:"Transparência reforçada para dados infantis.",r:"LGPD, art. 14, §2º"},
{id:"l77",d:"lgpd",t:"ce",e:"Cebraspe",q:"As informações sobre o tratamento de dados de crianças devem ser fornecidas de maneira simples, clara e acessível, com uso de recursos audiovisuais quando adequado.",a:true,c:"Consideradas as características físico-motoras, perceptivas, sensoriais, intelectuais e mentais do usuário.",r:"LGPD, art. 14, §6º"},
{id:"l78",d:"lgpd",t:"me",e:"FGV",q:"Uma clínica compartilha dados de saúde de pacientes com uma operadora para fins de seleção de riscos na contratação de planos. Essa conduta:",o:["é lícita se houver consentimento genérico.","é lícita por se tratar de tutela da saúde.","é vedada pela LGPD.","é lícita se os dados forem pseudonimizados.","depende apenas de autorização do conselho de medicina."],a:2,c:"Vedação expressa ao uso de dados de saúde para seleção de riscos.",r:"LGPD, art. 11, §5º"},
{id:"l79",d:"lgpd",t:"ce",e:"Cebraspe",q:"Os princípios e direitos previstos na LGPD não excluem outros previstos no ordenamento jurídico pátrio ou em tratados internacionais de que o Brasil seja parte.",a:true,c:"Cláusula de abertura.",r:"LGPD, art. 64"},
{id:"l80",d:"lgpd",t:"ce",e:"Cebraspe",q:"O princípio da prevenção consiste na adoção de medidas para prevenir a ocorrência de danos em virtude do tratamento de dados pessoais.",a:true,c:"Distinto do princípio da segurança, que trata da proteção contra acessos não autorizados e incidentes.",r:"LGPD, art. 6º, VIII"},
{id:"l81",d:"lgpd",t:"ce",e:"Cebraspe",q:"Pelo princípio da responsabilização e prestação de contas, basta ao agente adotar medidas de proteção, sendo desnecessário demonstrar sua eficácia.",a:false,c:"O agente deve demonstrar a adoção de medidas eficazes e capazes de comprovar o cumprimento.",r:"LGPD, art. 6º, X"},
{id:"l82",d:"lgpd",t:"ce",e:"Cebraspe",q:"O exercício regular de direitos em processo judicial, administrativo ou arbitral é hipótese legal de tratamento de dados pessoais.",a:true,c:"Base do art. 7º, VI.",r:"LGPD, art. 7º, VI"},
{id:"l83",d:"lgpd",t:"me",e:"IADES",q:"Uma rede varejista instala câmeras com reconhecimento facial para identificar clientes e oferecer promoções personalizadas. Considerando a LGPD, é correto afirmar que:",o:["o legítimo interesse basta, pois biometria não é dado sensível.","o dado biométrico é sensível, e o legítimo interesse não serve como base legal para seu tratamento.","basta afixar um aviso na entrada para dispensar qualquer base legal.","o tratamento é livre por ocorrer em espaço privado.","a LGPD não se aplica a imagens."],a:1,c:"Biometria vinculada à pessoa é dado sensível (art. 5º, II); o art. 11 não prevê legítimo interesse.",r:"LGPD, arts. 5º, II, e 11"},
{id:"l84",d:"lgpd",t:"ce",e:"Cebraspe",q:"A comunicação ou o uso compartilhado de dados pessoais de pessoa jurídica de direito público a pessoa de direito privado deve ser informado à ANPD e depende de consentimento do titular, salvo nas hipóteses de dispensa previstas na lei.",a:true,c:"Regra do art. 27, com exceções.",r:"LGPD, art. 27"},
{id:"a32",d:"anpd",t:"ce",e:"Cebraspe",q:"A primeira sanção aplicada pela ANPD, em 2023, recaiu sobre uma microempresa que tratava dados sem base legal e não havia indicado encarregado.",a:true,c:"Caso Telekall, marco da fase sancionatória.",r:"Processo sancionador ANPD (2023)"},
{id:"a33",d:"anpd",t:"ce",e:"Cebraspe",q:"A ANPD pode adotar medidas preventivas, como a suspensão cautelar de determinado tratamento, antes da conclusão do processo sancionador.",a:true,c:"Ex.: medida preventiva de 2024 sobre uso de dados para treinar IA.",r:"Res. CD/ANPD 1/2021"},
{id:"a34",d:"anpd",t:"ce",e:"Cebraspe",q:"A ANPD originalmente integrava a Presidência da República e foi transformada em autarquia de natureza especial pela Lei 14.460/2022, antes de se tornar agência reguladora em 2026.",a:true,c:"Trajetória: Lei 13.853/2019, Lei 14.460/2022, Lei 15.352/2026.",r:"Leis 13.853/2019, 14.460/2022 e 15.352/2026"},
{id:"a35",d:"anpd",t:"ce",e:"Cebraspe",q:"Compete à ANPD realizar auditorias, ou determinar sua realização, no âmbito da atividade de fiscalização sobre o tratamento de dados pessoais.",a:true,c:"Inclusive sobre o Poder Público.",r:"LGPD, art. 55-J, XVI"},
{id:"a36",d:"anpd",t:"ce",e:"Cebraspe",q:"Compete à ANPD promover ações de cooperação com autoridades de proteção de dados de outros países.",a:true,c:"De natureza internacional ou transnacional.",r:"LGPD, art. 55-J, IX"},
{id:"a37",d:"anpd",t:"ce",e:"Cebraspe",q:"A ANPD deve editar normas, orientações e procedimentos simplificados e diferenciados para microempresas, empresas de pequeno porte e startups.",a:true,c:"Base legal da Res. CD/ANPD 2/2022.",r:"LGPD, art. 55-J, XVIII"},
{id:"a38",d:"anpd",t:"me",e:"FGV",q:"Um agente de pequeno porte sofreu incidente de segurança com risco relevante aos titulares. O prazo para comunicação à ANPD é de:",o:["24 horas","3 dias úteis","6 dias úteis","15 dias corridos","30 dias"],a:2,c:"Prazo em dobro para agentes de pequeno porte (3 × 2 = 6 dias úteis).",r:"Res. CD/ANPD 15/2024; Res. CD/ANPD 2/2022"},
{id:"a39",d:"anpd",t:"ce",e:"Cebraspe",q:"O agente de tratamento deve prover ao encarregado os meios necessários ao exercício de suas atribuições.",a:true,c:"Inclui recursos humanos, técnicos e administrativos.",r:"Res. CD/ANPD 18/2024"},
{id:"a40",d:"anpd",t:"ce",e:"Cebraspe",q:"O Conselho Nacional de Proteção de Dados Pessoais e da Privacidade tem, entre suas competências, propor diretrizes estratégicas e fornecer subsídios para a Política Nacional de Proteção de Dados.",a:true,c:"Órgão consultivo.",r:"LGPD, art. 58-B"},
{id:"r21",d:"reg",t:"ce",e:"Cebraspe",q:"Consulta pública e audiência pública são o mesmo instrumento de participação social nas agências reguladoras.",a:false,c:"Consulta pública recebe contribuições por escrito sobre minutas; audiência pública é sessão para debate oral.",r:"Lei 13.848/2019, arts. 9º e 10"},
{id:"r22",d:"reg",t:"ce",e:"Cebraspe",q:"Na análise de impacto regulatório, a alternativa de não regular deve ser considerada entre as opções avaliadas.",a:true,c:"Comparar alternativas, inclusive a manutenção da situação.",r:"Decreto 10.411/2020, art. 6º"},
{id:"r23",d:"reg",t:"ce",e:"Cebraspe",q:"A regulação baseada em risco direciona os recursos de fiscalização para as atividades com maior probabilidade e impacto de dano.",a:true,c:"Lógica adotada no mapa de temas prioritários da ANPD.",r:"Teoria da regulação"},
{id:"r24",d:"reg",t:"ce",e:"Cebraspe",q:"A teoria do interesse público pressupõe que a regulação surge para corrigir falhas de mercado em benefício da sociedade.",a:true,c:"Contraponto à teoria da captura.",r:"Teorias da regulação"},
{id:"r25",d:"reg",t:"ce",e:"Cebraspe",q:"Os dirigentes de agências reguladoras podem ser exonerados livremente pelo Presidente da República, a qualquer tempo.",a:false,c:"Têm mandato fixo e estabilidade; a perda do cargo só ocorre nas hipóteses legais.",r:"Lei 9.986/2000, art. 9º"},
{id:"r26",d:"reg",t:"me",e:"FGV",q:"O instrumento que verifica, após a edição de um ato normativo, se os objetivos pretendidos foram alcançados é:",o:["análise de impacto regulatório","avaliação de resultado regulatório","agenda regulatória","consulta pública","sandbox regulatório"],a:1,c:"ARR é posterior; AIR é prévia.",r:"Decreto 10.411/2020"},
{id:"r27",d:"reg",t:"ce",e:"Cebraspe",q:"No sandbox regulatório, participantes recebem autorização temporária para testar modelos inovadores com regras diferenciadas, sob supervisão do regulador.",a:true,c:"A ANPD já lançou sandbox sobre IA e proteção de dados.",r:"LC 182/2021, art. 11"},
{id:"g19",d:"digital",t:"ce",e:"Cebraspe",q:"O Decreto 12.622/2025 regulamentou aspectos do ECA Digital e atribuiu à ANPD a competência para zelar por sua aplicação.",a:true,c:"Editado na mesma data da lei.",r:"Decreto 12.622/2025"},
{id:"g20",d:"digital",t:"ce",e:"Cebraspe",q:"O ECA Digital prevê sanções que vão de advertência a suspensão de atividades, sem prejuízo das sanções da LGPD.",a:true,c:"As obrigações e sanções se acumulam.",r:"Lei 15.211/2025"},
{id:"g21",d:"digital",t:"ce",e:"Cebraspe",q:"A vigência do ECA Digital foi fixada para 17 de março de 2026.",a:true,c:"Data confirmada pela Lei 15.352/2026.",r:"Lei 15.211/2025; Lei 15.352/2026"},
{id:"g22",d:"digital",t:"ce",e:"Cebraspe",q:"O Marco Civil da Internet garante ao usuário a exclusão definitiva dos dados pessoais fornecidos a determinada aplicação, a seu requerimento, ao término da relação entre as partes, ressalvadas as hipóteses de guarda obrigatória.",a:true,c:"Direito previsto no art. 7º, X.",r:"Lei 12.965/2014, art. 7º, X"},
{id:"g23",d:"digital",t:"ce",e:"Cebraspe",q:"Segundo o Marco Civil, a disciplina do uso da internet tem como um de seus princípios a proteção dos dados pessoais, na forma da lei.",a:true,c:"Princípio do art. 3º, III.",r:"Lei 12.965/2014, art. 3º, III"},
{id:"g24",d:"digital",t:"ce",e:"Cebraspe",q:"Pela LAI, é dever do Estado controlar o acesso e a divulgação de informações sigilosas, assegurando a sua proteção.",a:true,c:"Ao lado do dever de transparência.",r:"Lei 12.527/2011, art. 25"},
{id:"g25",d:"digital",t:"me",e:"FGV",q:"Um cidadão pede a um órgão federal, com base na LAI, cópia do prontuário médico de um vizinho. O órgão deve:",o:["fornecer, pois a informação é pública.","fornecer, desde que o pedido seja motivado.","negar, pois se trata de informação pessoal relativa à intimidade de terceiro, de acesso restrito.","fornecer após 5 anos.","encaminhar o pedido à ANPD para decisão."],a:2,c:"Informações pessoais têm acesso restrito por até 100 anos, salvo previsão legal ou consentimento.",r:"Lei 12.527/2011, art. 31"},
{id:"t20",d:"ti",t:"ce",e:"Cebraspe",q:"A anonimização pela simples remoção de nomes e CPFs garante que o titular não possa ser reidentificado.",a:false,c:"Quase-identificadores (CEP, data de nascimento, sexo) permitem reidentificação por cruzamento.",r:"Anonimização"},
{id:"t21",d:"ti",t:"ce",e:"Cebraspe",q:"No modelo IaaS, o provedor fornece infraestrutura (servidores, armazenamento, rede), e o cliente gerencia sistemas operacionais e aplicações.",a:true,c:"Diferente de PaaS e SaaS.",r:"Computação em nuvem"},
{id:"t22",d:"ti",t:"ce",e:"Cebraspe",q:"Ransomware é um tipo de código malicioso que torna os dados inacessíveis, geralmente por criptografia, e exige resgate para restabelecer o acesso.",a:true,c:"Backups isolados são a principal mitigação.",r:"Ameaças"},
{id:"t23",d:"ti",t:"ce",e:"Cebraspe",q:"A explicabilidade em IA exige, necessariamente, a divulgação integral do código-fonte do sistema.",a:false,c:"Exige informar critérios e lógica da decisão, observados os segredos comercial e industrial.",r:"LGPD, art. 20, §1º"},
{id:"t24",d:"ti",t:"ce",e:"Cebraspe",q:"O AI Act europeu adota abordagem baseada em risco, impondo obrigações mais rígidas aos sistemas de IA de alto risco.",a:true,c:"Lógica semelhante à do PL 2338/2023.",r:"Regulamento (UE) 2024/1689"},
{id:"t25",d:"ti",t:"ce",e:"Cebraspe",q:"Engenharia social explora a confiança e o comportamento humano para obter acesso a informações ou sistemas.",a:true,c:"Ex.: phishing, pretexting.",r:"Ameaças"},
{id:"t26",d:"ti",t:"me",e:"FGV",q:"A técnica que substitui um identificador direto por um código, mantendo em local separado a tabela que permite a reassociação, é a:",o:["anonimização","pseudonimização","criptografia de disco","compressão","minimização"],a:1,c:"Pseudonimização (LGPD, art. 13, §4º).",r:"LGPD, art. 13, §4º"},
{id:"d18",d:"adm",t:"ce",e:"Cebraspe",q:"Os atos administrativos devem ser motivados quando decidam recursos administrativos.",a:true,c:"Hipótese do art. 50, V.",r:"Lei 9.784/1999, art. 50, V"},
{id:"d19",d:"adm",t:"ce",e:"Cebraspe",q:"A Administração deve anular seus próprios atos quando eivados de vício de legalidade e pode revogá-los por motivo de conveniência ou oportunidade, respeitados os direitos adquiridos.",a:true,c:"Autotutela.",r:"Lei 9.784/1999, art. 53"},
{id:"d20",d:"adm",t:"ce",e:"Cebraspe",q:"Em processo administrativo, a intimação deve ser feita com antecedência mínima de três dias úteis quanto à data de comparecimento.",a:true,c:"Prazo do art. 26, §2º.",r:"Lei 9.784/1999, art. 26, §2º"},
{id:"d21",d:"adm",t:"ce",e:"Cebraspe",q:"O diálogo competitivo é modalidade de licitação destinada a contratações em que a Administração busca desenvolver soluções com licitantes previamente selecionados.",a:true,c:"Novidade da Lei 14.133/2021.",r:"Lei 14.133/2021, art. 32"},
{id:"d22",d:"adm",t:"me",e:"FGV",q:"A competência para aplicar sanções da LGPD é exclusiva da ANPD. Esse arranjo reflete, sobretudo, o princípio administrativo da:",o:["especialidade","publicidade","moralidade","motivação","autotutela"],a:0,c:"Entidades da administração indireta atuam nas finalidades definidas em lei (especialidade).",r:"Princípios administrativos"},
{id:"c12",d:"const",t:"ce",e:"Cebraspe",q:"A casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem consentimento do morador, salvo em flagrante delito, desastre, para prestar socorro ou, durante o dia, por determinação judicial.",a:true,c:"Art. 5º, XI.",r:"CF, art. 5º, XI"},
{id:"c13",d:"const",t:"ce",e:"Cebraspe",q:"É assegurado a todos o acesso à informação e resguardado o sigilo da fonte, quando necessário ao exercício profissional.",a:true,c:"Art. 5º, XIV.",r:"CF, art. 5º, XIV"},
{id:"c14",d:"const",t:"ce",e:"Cebraspe",q:"A família, a sociedade e o Estado devem assegurar à criança e ao adolescente, com absoluta prioridade, os direitos fundamentais, colocando-os a salvo de toda forma de negligência, exploração e opressão.",a:true,c:"Base do ECA Digital.",r:"CF, art. 227"},
{id:"c15",d:"const",t:"ce",e:"Cebraspe",q:"O habeas data é cabível para a retificação de dados, quando não se prefira fazê-lo por processo sigiloso, judicial ou administrativo.",a:true,c:"Art. 5º, LXXII, b.",r:"CF, art. 5º, LXXII, b"},
{id:"e10",d:"etica",t:"ce",e:"Cebraspe",q:"Pelo Código de Ética, é vedado ao servidor usar o cargo ou função para obter qualquer favorecimento, para si ou para outrem.",a:true,c:"Vedação do item XV, a.",r:"Decreto 1.171/1994, XV, a"},
{id:"e11",d:"etica",t:"ce",e:"Cebraspe",q:"Configura conflito de interesses, durante o exercício do cargo, divulgar ou fazer uso de informação privilegiada obtida em razão das atividades exercidas.",a:true,c:"Hipótese do art. 5º, I.",r:"Lei 12.813/2013, art. 5º, I"},
{id:"e12",d:"etica",t:"ce",e:"Cebraspe",q:"A Lei 8.112/1990 prevê como penalidades disciplinares, entre outras, a advertência, a suspensão e a demissão.",a:true,c:"Rol do art. 127.",r:"Lei 8.112/1990, art. 127"},
{id:"p13",d:"port",t:"ce",e:"Cebraspe",q:"Em “A ANPD, que se tornou agência reguladora em 2026, ampliou sua atuação”, as vírgulas isolam oração adjetiva explicativa.",a:true,c:"A oração acrescenta informação sobre termo já determinado.",r:"Pontuação"},
{id:"p14",d:"port",t:"ce",e:"Cebraspe",q:"A substituição de “contudo” por “portanto” em “A lei avançou; contudo, faltam regulamentos” preservaria o sentido original.",a:false,c:"“Contudo” é adversativo; “portanto” é conclusivo.",r:"Conectivos"},
{id:"p15",d:"port",t:"ce",e:"Cebraspe",q:"Em “Devem existir mecanismos de controle”, o verbo “dever” concorda com “mecanismos”.",a:true,c:"Locução verbal com “existir” (pessoal) concorda com o sujeito.",r:"Concordância verbal"},
{id:"p16",d:"port",t:"me",e:"FGV",q:"Assinale a frase com emprego correto do acento grave.",o:["A norma se aplica à todos os agentes.","Referiu-se à resoluções antigas.","O relatório foi entregue à agência.","Começou à analisar o caso.","Ficou frente à frente com o diretor."],a:2,c:"Entregar a + a agência = à. Nas demais não há artigo feminino ou há palavra repetida/verbo.",r:"Crase"},
{id:"i10",d:"ing",t:"ce",e:"Cebraspe",q:"In “Controllers shall implement appropriate safeguards”, the modal “shall” expresses obligation.",a:true,c:"Em textos normativos, shall = deve.",r:"Modal verbs"},
{id:"i11",d:"ing",t:"ce",e:"Cebraspe",q:"The word “lawful” in “lawful basis for processing” means legal or permitted by law.",a:true,c:"Lawful basis = base legal.",r:"Vocabulary"},
{id:"i12",d:"ing",t:"ce",e:"Cebraspe",q:"In “Despite the new rules, breaches increased”, “despite” introduces a cause.",a:false,c:"Despite introduz concessão (apesar de).",r:"Connectors"}
);

// ===== AMPLIAÇÃO 3 (nov/2026): mais questões, técnica de redação, discursivas curtas, flashcards, lei seca =====
QB.push(
{id:"l85",d:"lgpd",t:"ce",e:"Cebraspe",q:"Para a LGPD, o simples armazenamento de dados pessoais configura operação de tratamento.",a:true,c:"Tratamento é toda operação com dados pessoais, da coleta à eliminação, incluindo armazenamento.",r:"LGPD, art. 5º, X"},
{id:"l86",d:"lgpd",t:"ce",e:"Cebraspe",q:"O bloqueio consiste na exclusão definitiva de dado ou de conjunto de dados armazenados em banco de dados.",a:false,c:"Bloqueio é a suspensão temporária de qualquer operação de tratamento, com guarda do dado. A exclusão é a eliminação.",r:"LGPD, art. 5º, XIII e XIV"},
{id:"l87",d:"lgpd",t:"ce",e:"Cebraspe",q:"O relatório de impacto à proteção de dados pessoais é documentação do controlador que descreve os processos de tratamento que podem gerar riscos às liberdades civis e aos direitos fundamentais, bem como medidas, salvaguardas e mecanismos de mitigação de risco.",a:true,c:"Definição legal do RIPD.",r:"LGPD, art. 5º, XVII"},
{id:"l88",d:"lgpd",t:"ce",e:"Cebraspe",q:"A anonimização pressupõe a utilização de meios técnicos razoáveis e disponíveis no momento do tratamento.",a:true,c:"Por isso a anonimização é avaliada conforme a tecnologia da época.",r:"LGPD, art. 5º, XI"},
{id:"l89",d:"lgpd",t:"ce",e:"Cebraspe",q:"Em nenhum caso a totalidade dos dados pessoais de banco de dados de segurança pública poderá ser tratada por pessoa de direito privado, salvo por aquela que possua capital integralmente constituído pelo poder público.",a:true,c:"Limite expresso ao tratamento privado de bases de segurança pública.",r:"LGPD, art. 4º, §4º"},
{id:"l90",d:"lgpd",t:"ce",e:"Cebraspe",q:"A base legal da tutela da saúde pode ser invocada por qualquer empresa que comercialize produtos relacionados ao bem-estar.",a:false,c:"Vale exclusivamente em procedimento realizado por profissionais de saúde, serviços de saúde ou autoridade sanitária.",r:"LGPD, art. 7º, VIII"},
{id:"l91",d:"lgpd",t:"ce",e:"Cebraspe",q:"Os dados utilizados para a formação do perfil comportamental de determinada pessoa natural, se identificada, poderão ser igualmente considerados dados pessoais.",a:true,c:"Perfilamento atrai a proteção da lei.",r:"LGPD, art. 12, §2º"},
{id:"l92",d:"lgpd",t:"ce",e:"Cebraspe",q:"Na realização de estudos em saúde pública, o órgão de pesquisa pode transferir os dados pessoais a terceiros, desde que pseudonimizados.",a:false,c:"O órgão de pesquisa é responsável pela segurança, e a transferência a terceiro não é permitida em circunstância alguma.",r:"LGPD, art. 13, §2º"},
{id:"l93",d:"lgpd",t:"ce",e:"Cebraspe",q:"Os direitos do titular são exercidos mediante requerimento expresso do titular ou de representante legalmente constituído, dirigido ao agente de tratamento.",a:true,c:"Forma de exercício prevista no art. 18, §3º.",r:"LGPD, art. 18, §3º"},
{id:"l94",d:"lgpd",t:"ce",e:"Cebraspe",q:"O Poder Público deve informar as hipóteses em que realiza tratamento de dados pessoais, fornecendo informações claras e atualizadas em veículos de fácil acesso, preferencialmente em seus sítios eletrônicos.",a:true,c:"Transparência ativa no setor público.",r:"LGPD, art. 23, I"},
{id:"l95",d:"lgpd",t:"ce",e:"Cebraspe",q:"O operador deve realizar o tratamento segundo as instruções fornecidas pelo controlador, que verificará a observância das próprias instruções e das normas sobre a matéria.",a:true,c:"Relação controlador–operador.",r:"LGPD, art. 39"},
{id:"l96",d:"lgpd",t:"ce",e:"Cebraspe",q:"A ANPD pode estabelecer hipóteses de dispensa da necessidade de indicação do encarregado, conforme a natureza e o porte da entidade ou o volume de operações de tratamento.",a:true,c:"Fundamento da dispensa para agentes de pequeno porte.",r:"LGPD, art. 41, §3º"},
{id:"l97",d:"lgpd",t:"ce",e:"Cebraspe",q:"Os controladores que estiverem diretamente envolvidos no tratamento do qual decorreram danos ao titular respondem solidariamente.",a:true,c:"Solidariedade entre controladores.",r:"LGPD, art. 42, §1º, II"},
{id:"l98",d:"lgpd",t:"ce",e:"Cebraspe",q:"Aquele que reparar o dano ao titular tem direito de regresso contra os demais responsáveis, na medida de sua participação no evento danoso.",a:true,c:"Direito de regresso.",r:"LGPD, art. 42, §4º"},
{id:"l99",d:"lgpd",t:"ce",e:"Cebraspe",q:"As sanções administrativas da LGPD são aplicadas após procedimento administrativo que possibilite a ampla defesa, de forma gradativa, isolada ou cumulativa.",a:true,c:"Consideram-se os parâmetros do §1º do art. 52.",r:"LGPD, art. 52, §1º"},
{id:"l100",d:"lgpd",t:"ce",e:"Cebraspe",q:"O produto da arrecadação das multas aplicadas pela ANPD é destinado ao Fundo de Defesa de Direitos Difusos.",a:true,c:"Destinação legal das multas.",r:"LGPD, art. 52, §5º"},
{id:"l101",d:"lgpd",t:"ce",e:"Cebraspe",q:"Os vazamentos individuais ou os acessos não autorizados podem ser objeto de conciliação direta entre controlador e titular e, caso não haja acordo, o controlador estará sujeito às penalidades da lei.",a:true,c:"Previsão do §7º do art. 52.",r:"LGPD, art. 52, §7º"},
{id:"l102",d:"lgpd",t:"me",e:"FGV",q:"Um aplicativo de transporte quer usar os dados de corridas, coletados para executar o serviço, para vender perfis de deslocamento a anunciantes. O princípio da LGPD mais diretamente violado, na ausência de nova base legal e de informação ao titular, é o da:",o:["qualidade dos dados","finalidade","livre acesso","segurança","prevenção"],a:1,c:"Tratamento posterior incompatível com os propósitos informados viola a finalidade (e a adequação).",r:"LGPD, art. 6º, I"},
{id:"l103",d:"lgpd",t:"me",e:"IADES",q:"Uma prefeitura contrata empresa de tecnologia para hospedar o cadastro de beneficiários de um programa social, seguindo instruções do município. Nessa relação, a empresa é:",o:["controladora","operadora","encarregada","titular","autoridade nacional"],a:1,c:"Quem trata dados em nome do controlador é operador.",r:"LGPD, art. 5º, VII"},
{id:"l104",d:"lgpd",t:"ce",e:"Cebraspe",q:"É possível o tratamento posterior de dados pessoais de acesso público para novas finalidades, desde que observados propósitos legítimos e específicos e preservados os direitos do titular.",a:true,c:"Regra do §7º do art. 7º.",r:"LGPD, art. 7º, §7º"},
{id:"a41",d:"anpd",t:"ce",e:"Cebraspe",q:"Os regulamentos e as normas editados pela ANPD devem ser precedidos de consulta e audiência públicas, bem como de análises de impacto regulatório.",a:true,c:"Exigência de participação e de AIR.",r:"LGPD, art. 55-J, §2º"},
{id:"a42",d:"anpd",t:"ce",e:"Cebraspe",q:"Compete à ANPD implementar mecanismos simplificados, inclusive por meio eletrônico, para o registro de reclamações sobre o tratamento de dados pessoais em desconformidade com a lei.",a:true,c:"Competência do inciso XXIV.",r:"LGPD, art. 55-J, XXIV"},
{id:"a43",d:"anpd",t:"ce",e:"Cebraspe",q:"Pelo regulamento de incidentes, a comunicação ao titular deve usar linguagem simples e ser feita de forma direta e individualizada, caso seja possível identificá-lo.",a:true,c:"Se não for possível, usa-se divulgação por meios disponíveis.",r:"Res. CD/ANPD 15/2024"},
{id:"a44",d:"anpd",t:"me",e:"FGV",q:"Pelo regulamento de comunicação de incidentes, o incidente pode acarretar risco ou dano relevante quando afetar significativamente interesses e direitos fundamentais dos titulares e, cumulativamente, envolver ao menos um dos seguintes critérios, EXCETO:",o:["dados pessoais sensíveis","dados de crianças, adolescentes ou idosos","dados financeiros ou de autenticação em sistemas","dados em larga escala","dados já tornados manifestamente públicos pelo titular"],a:4,c:"Os critérios incluem sensíveis, vulneráveis, financeiros, autenticação, sigilo legal e larga escala.",r:"Res. CD/ANPD 15/2024, art. 5º"},
{id:"a45",d:"anpd",t:"ce",e:"Cebraspe",q:"A indicação do encarregado deve ser feita por ato formal do agente de tratamento, do qual constem as formas de atuação e as atividades a serem desempenhadas.",a:true,c:"Documento escrito, datado e assinado.",r:"Res. CD/ANPD 18/2024"},
{id:"a46",d:"anpd",t:"ce",e:"Cebraspe",q:"As normas corporativas globais destinam-se às transferências internacionais de dados entre organizações do mesmo grupo ou conglomerado, com caráter vinculante para seus membros.",a:true,c:"Mecanismo do art. 33, II, c, detalhado no regulamento.",r:"Res. CD/ANPD 19/2024"},
{id:"a47",d:"anpd",t:"ce",e:"Cebraspe",q:"Agentes de tratamento de pequeno porte podem organizar-se por meio de entidades de representação para fins de negociação, mediação e conciliação de reclamações apresentadas por titulares.",a:true,c:"Facilidade prevista no regulamento.",r:"Res. CD/ANPD 2/2022"},
{id:"a48",d:"anpd",t:"ce",e:"Cebraspe",q:"Pelo regulamento de dosimetria, a advertência pode ser aplicada quando a infração for leve ou média e não houver reincidência específica.",a:true,c:"Também cabe quando houver necessidade de impor medidas corretivas.",r:"Res. CD/ANPD 4/2023"},
{id:"r28",d:"reg",t:"ce",e:"Cebraspe",q:"A agência reguladora deve observar a devida adequação entre meios e fins, vedada a imposição de obrigações, restrições e sanções em medida superior àquela necessária ao atendimento do interesse público.",a:true,c:"Proporcionalidade regulatória.",r:"Lei 13.848/2019, art. 4º"},
{id:"r29",d:"reg",t:"ce",e:"Cebraspe",q:"A agência reguladora deve indicar os pressupostos de fato e de direito que determinarem suas decisões, inclusive a respeito da edição ou não de atos normativos.",a:true,c:"Dever de motivação.",r:"Lei 13.848/2019, art. 5º"},
{id:"r30",d:"reg",t:"ce",e:"Cebraspe",q:"Os membros do conselho diretor das agências reguladoras federais têm mandato de cinco anos, vedada a recondução.",a:true,c:"Regra geral da Lei 9.986/2000, com a redação da Lei 13.848/2019. A ANPD segue regra própria na LGPD; confira o texto consolidado.",r:"Lei 9.986/2000, art. 6º"},
{id:"r31",d:"reg",t:"ce",e:"Cebraspe",q:"Na regulação por taxa de retorno, a empresa regulada tende a investir em capital além do eficiente, fenômeno conhecido como efeito Averch-Johnson.",a:true,c:"Crítica clássica à regulação pelo custo do serviço.",r:"Economia da regulação"},
{id:"r32",d:"reg",t:"me",e:"FGV",q:"Segundo Ronald Coase, na ausência de custos de transação e com direitos de propriedade bem definidos:",o:["a regulação estatal é sempre necessária.","as partes negociam e chegam a um resultado eficiente, independentemente da alocação inicial dos direitos.","as externalidades não podem ser corrigidas.","o monopólio natural desaparece.","o Estado deve tributar toda externalidade."],a:1,c:"Teorema de Coase.",r:"Economia da regulação"},
{id:"r33",d:"reg",t:"ce",e:"Cebraspe",q:"As agências reguladoras devem elaborar plano de gestão anual, alinhado ao plano estratégico.",a:true,c:"Instrumento de planejamento consolidado.",r:"Lei 13.848/2019, art. 18"},
{id:"g26",d:"digital",t:"ce",e:"Cebraspe",q:"Pelo Marco Civil, o provedor responsável pela guarda somente será obrigado a disponibilizar os registros de conexão e de acesso a aplicações mediante ordem judicial.",a:true,c:"Ressalvado o acesso a dados cadastrais por autoridades com competência legal.",r:"Lei 12.965/2014, art. 10, §1º"},
{id:"g27",d:"digital",t:"ce",e:"Cebraspe",q:"Em operação de coleta de dados por provedor de aplicações em que ao menos um dos atos ocorra em território nacional, deve ser respeitada a legislação brasileira, ainda que a empresa seja sediada no exterior.",a:true,c:"Desde que oferte serviço ao público brasileiro ou tenha integrante do grupo no Brasil.",r:"Lei 12.965/2014, art. 11"},
{id:"g28",d:"digital",t:"ce",e:"Cebraspe",q:"Pela LAI, é dever dos órgãos e entidades públicas promover, independentemente de requerimentos, a divulgação de informações de interesse coletivo ou geral por eles produzidas ou custodiadas.",a:true,c:"Transparência ativa.",r:"Lei 12.527/2011, art. 8º"},
{id:"g29",d:"digital",t:"ce",e:"Cebraspe",q:"No caso de indeferimento de acesso a informações, o interessado pode interpor recurso no prazo de dez dias, contado da ciência da decisão.",a:true,c:"Dirigido à autoridade hierarquicamente superior.",r:"Lei 12.527/2011, art. 15"},
{id:"g30",d:"digital",t:"me",e:"FGV",q:"Uma plataforma de jogos on-line com acesso provável por adolescentes pretende manter caixas de recompensa pagas com itens aleatórios. À luz do ECA Digital, a prática é:",o:["permitida com autodeclaração de idade.","permitida com aviso de probabilidades.","vedada.","permitida para maiores de 12 anos.","permitida mediante seguro."],a:2,c:"A lei veda loot boxes em jogos direcionados a crianças e adolescentes ou de acesso provável por eles.",r:"Lei 15.211/2025"},
{id:"t27",d:"ti",t:"ce",e:"Cebraspe",q:"O protocolo TLS protege a confidencialidade e a integridade dos dados em trânsito entre cliente e servidor.",a:true,c:"Base do HTTPS.",r:"Segurança de redes"},
{id:"t28",d:"ti",t:"ce",e:"Cebraspe",q:"No modelo de confiança zero (zero trust), usuários e dispositivos dentro da rede interna são considerados confiáveis por padrão.",a:false,c:"O lema é “nunca confiar, sempre verificar”, inclusive dentro do perímetro.",r:"Arquitetura de segurança"},
{id:"t29",d:"ti",t:"ce",e:"Cebraspe",q:"O uso de salt no armazenamento de senhas dificulta ataques com tabelas pré-computadas.",a:true,c:"O salt torna único o hash de cada senha.",r:"Criptografia"},
{id:"t30",d:"ti",t:"ce",e:"Cebraspe",q:"A norma ISO/IEC 27005 trata da gestão de riscos de segurança da informação.",a:true,c:"Complementa a 27001.",r:"ISO/IEC 27005"},
{id:"t31",d:"ti",t:"ce",e:"Cebraspe",q:"A criptografia de dados em repouso protege as informações armazenadas mesmo em caso de acesso físico indevido à mídia.",a:true,c:"Medida técnica alinhada ao art. 46 da LGPD.",r:"Criptografia"},
{id:"t32",d:"ti",t:"me",e:"FGV",q:"Um servidor recebe e-mail que imita o setor de TI pedindo a senha para “atualização cadastral”. O ataque descrito é:",o:["negação de serviço","phishing","injeção de SQL","força bruta","sniffing"],a:1,c:"Engenharia social por mensagem fraudulenta.",r:"Ameaças"},
{id:"d23",d:"adm",t:"ce",e:"Cebraspe",q:"Os atos do processo administrativo não dependem de forma determinada, senão quando a lei expressamente a exigir.",a:true,c:"Informalismo moderado.",r:"Lei 9.784/1999, art. 22"},
{id:"d24",d:"adm",t:"ce",e:"Cebraspe",q:"Inexistindo disposição específica, os atos do órgão responsável pelo processo e dos administrados devem ser praticados no prazo de cinco dias, salvo motivo de força maior.",a:true,c:"O prazo pode ser dilatado até o dobro, mediante justificação.",r:"Lei 9.784/1999, art. 24"},
{id:"d25",d:"adm",t:"ce",e:"Cebraspe",q:"O recurso administrativo é dirigido à autoridade que proferiu a decisão, a qual, se não a reconsiderar em cinco dias, o encaminhará à autoridade superior.",a:true,c:"Juízo de reconsideração.",r:"Lei 9.784/1999, art. 56, §1º"},
{id:"d26",d:"adm",t:"ce",e:"Cebraspe",q:"Nas esferas administrativa, controladora e judicial, não se decidirá com base em valores jurídicos abstratos sem que sejam consideradas as consequências práticas da decisão.",a:true,c:"Consequencialismo introduzido na LINDB pela Lei 13.655/2018.",r:"LINDB, art. 20"},
{id:"d27",d:"adm",t:"ce",e:"Cebraspe",q:"Na Lei 14.133/2021, o pregão é a modalidade obrigatória para aquisição de bens e serviços comuns.",a:true,c:"Critério de julgamento: menor preço ou maior desconto.",r:"Lei 14.133/2021, art. 6º, XLI"},
{id:"c16",d:"const",t:"ce",e:"Cebraspe",q:"Aos litigantes, em processo judicial ou administrativo, e aos acusados em geral são assegurados o contraditório e a ampla defesa.",a:true,c:"Vale para o processo sancionador da ANPD.",r:"CF, art. 5º, LV"},
{id:"c17",d:"const",t:"ce",e:"Cebraspe",q:"O direito de petição aos Poderes Públicos em defesa de direitos ou contra ilegalidade ou abuso de poder é assegurado a todos, independentemente do pagamento de taxas.",a:true,c:"Art. 5º, XXXIV, a.",r:"CF, art. 5º, XXXIV"},
{id:"c18",d:"const",t:"ce",e:"Cebraspe",q:"A investidura em cargo ou emprego público depende de aprovação prévia em concurso público de provas ou de provas e títulos, ressalvadas as nomeações para cargo em comissão.",a:true,c:"Regra do concurso público.",r:"CF, art. 37, II"},
{id:"e13",d:"etica",t:"ce",e:"Cebraspe",q:"É dever do servidor público federal guardar sigilo sobre assunto da repartição.",a:true,c:"Especialmente relevante para quem lida com dados pessoais.",r:"Lei 8.112/1990, art. 116, VIII"},
{id:"e14",d:"etica",t:"ce",e:"Cebraspe",q:"Pelo Código de Ética, toda ausência injustificada do servidor de seu local de trabalho é fator de desmoralização do serviço público.",a:true,c:"Regra deontológica do item XII.",r:"Decreto 1.171/1994, XII"},
{id:"i13",d:"ing",t:"ce",e:"Cebraspe",q:"In “The regulator may impose fines”, the modal “may” indicates possibility or permission.",a:true,c:"Diferente de shall/must (obrigação).",r:"Modal verbs"},
{id:"i14",d:"ing",t:"ce",e:"Cebraspe",q:"The phrasal verb “comply with” means to act in accordance with a rule.",a:true,c:"Comply with the law = cumprir a lei.",r:"Vocabulary"},
// ---- Técnica de redação (ajuda para a discursiva)
{id:"x01",d:"port",t:"me",e:"Redação",q:"Tema: “O papel da ANPD na proteção de crianças no ambiente digital”. Qual frase funciona melhor como TESE na introdução?",o:["A internet mudou muito a vida das pessoas nos últimos anos.","Com o ECA Digital, a ANPD passa a ser peça central na proteção de crianças on-line, o que exige regulamentação técnica e fiscalização baseada em risco.","Existem muitas leis no Brasil sobre vários assuntos.","As crianças gostam de jogos eletrônicos.","Será que a ANPD consegue fiscalizar tudo?"],a:1,c:"A tese responde ao tema, toma posição e antecipa os dois eixos do desenvolvimento.",r:"Estrutura: introdução"},
{id:"x02",d:"port",t:"me",e:"Redação",q:"Qual conectivo inicia adequadamente o parágrafo de CONCLUSÃO?",o:["Outrossim,","Em contrapartida,","Portanto,","Por exemplo,","Ademais,"],a:2,c:"“Portanto” é conclusivo. “Outrossim” e “ademais” somam; “em contrapartida” opõe.",r:"Conectivos"},
{id:"x03",d:"port",t:"me",e:"Redação",q:"Qual trecho fundamenta melhor um argumento em prova discursiva de agência reguladora?",o:["Todo mundo sabe que vazamentos são ruins.","Na minha opinião, as empresas deveriam cuidar mais dos dados.","A LGPD impõe ao controlador a comunicação de incidentes com risco relevante (art. 48), em prazo que a ANPD fixou em três dias úteis.","Vazamentos acontecem desde sempre.","É um absurdo o que fazem com nossos dados."],a:2,c:"Fundamentação normativa precisa, com artigo e regulamento.",r:"Argumentação"},
{id:"x04",d:"port",t:"me",e:"Redação",q:"Para evitar a repetição de “a ANPD” em “A ANPD fiscaliza. A ANPD também orienta”, a melhor reescrita é:",o:["A ANPD fiscaliza. A mesma também orienta.","A ANPD fiscaliza e, além disso, orienta os agentes de tratamento.","A ANPD fiscaliza. Ela, a ANPD, orienta.","Fiscaliza a ANPD. Orienta a ANPD.","A ANPD fiscaliza, onde também orienta."],a:1,c:"Coordenação com elipse do sujeito. “A mesma” e “onde” são usos condenados.",r:"Coesão"},
{id:"x05",d:"port",t:"ce",e:"Redação",q:"Em prova discursiva, citar o dispositivo legal pertinente (por exemplo, “LGPD, art. 6º, III”) fortalece a fundamentação, desde que a citação esteja correta.",a:true,c:"Citação errada prejudica; na dúvida, cite a lei sem o número do artigo.",r:"Argumentação"},
{id:"x06",d:"port",t:"ce",e:"Redação",q:"Em texto dissertativo de concurso, recomenda-se o uso da primeira pessoa do singular e de expressões coloquiais para aproximar o leitor.",a:false,c:"Prefira impessoalidade e registro formal.",r:"Registro"},
{id:"x07",d:"port",t:"ce",e:"Redação",q:"Quando o comando da questão discursiva lista tópicos a abordar, deixar de tratar um deles costuma implicar perda integral dos pontos daquele quesito.",a:true,c:"A correção segue um espelho por quesito. Responda a todos, de preferência na ordem pedida.",r:"Estratégia de prova"},
{id:"x08",d:"port",t:"me",e:"Redação",q:"Qual alternativa apresenta um parágrafo de desenvolvimento com ideia central, fundamento e exemplo?",o:["A biometria é importante. Existem muitos riscos. É preciso cuidado.","O reconhecimento facial exige cautela, pois a biometria é dado sensível (LGPD, art. 5º, II) e não pode ser trocada após um vazamento. Em estádios e no comércio, por exemplo, o uso sem alternativa ao titular amplia o risco de vigilância indevida.","A biometria, o reconhecimento facial, os dados, as empresas, todos estão envolvidos.","Primeiramente, a biometria. Segundamente, os riscos.","Não se sabe ao certo o que é biometria."],a:1,c:"Tópico frasal + fundamento legal + exemplo concreto.",r:"Estrutura: desenvolvimento"},
{id:"x09",d:"port",t:"ce",e:"Redação",q:"A conclusão de um texto dissertativo deve trazer argumento inteiramente novo, não mencionado no desenvolvimento.",a:false,c:"A conclusão retoma a tese e apresenta síntese ou proposta coerente com o que foi desenvolvido.",r:"Estrutura: conclusão"},
{id:"x10",d:"port",t:"me",e:"Redação",q:"Assinale a frase adequada ao registro formal exigido na discursiva.",o:["As empresas tão nem aí pra privacidade.","A gente vê que a lei não pegou.","Observa-se que parte dos agentes de tratamento ainda não se adequou à legislação.","Tipo assim, a ANPD deveria multar mais.","A lei é top, mas falta fiscalização."],a:2,c:"Impessoalidade (“observa-se”) e vocabulário técnico.",r:"Registro"},
{id:"x11",d:"port",t:"ce",e:"Redação",q:"Nas provas discursivas, o texto que foge totalmente ao tema proposto costuma receber nota zero.",a:true,c:"Leia o comando duas vezes e sublinhe o que se pede antes de escrever.",r:"Estratégia de prova"},
{id:"x12",d:"port",t:"me",e:"Redação",q:"Em “A fiscalização é necessária; ______, deve ser proporcional ao porte do agente”, a lacuna é corretamente preenchida por:",o:["porque","contudo","pois","portanto que","visto que"],a:1,c:"Relação de ressalva (adversativa).",r:"Conectivos"}
);

// Questões discursivas curtas com espelho de correção (5 a 10 linhas cada)
const ESSAY_DRILLS = [
 {q:"Diferencie controlador, operador e encarregado na LGPD e indique quais deles são agentes de tratamento.", pts:["Controlador: a quem competem as decisões sobre o tratamento (art. 5º, VI).","Operador: trata dados em nome do controlador (art. 5º, VII).","Encarregado: canal de comunicação entre controlador, titulares e ANPD (art. 5º, VIII).","Agentes de tratamento são apenas controlador e operador (art. 5º, IX)."]},
 {q:"Explique por que o legítimo interesse não pode fundamentar o tratamento de dados pessoais sensíveis e cite duas bases legais cabíveis para esses dados.", pts:["Dados sensíveis têm rol próprio de bases legais (art. 11).","O art. 11 não prevê legítimo interesse nem proteção do crédito.","Base 1: consentimento específico e destacado.","Base 2: obrigação legal, políticas públicas, pesquisa, tutela da saúde, proteção da vida ou prevenção à fraude em autenticação."]},
 {q:"Descreva o dever de comunicação de incidente de segurança: quando comunicar, a quem e em que prazo.", pts:["Só incidentes que possam acarretar risco ou dano relevante (art. 48).","Comunicação à ANPD e aos titulares.","Prazo de 3 dias úteis do conhecimento (Res. CD/ANPD 15/2024).","Agente de pequeno porte tem prazo em dobro; todos os incidentes são registrados por 5 anos."]},
 {q:"O que é regulação responsiva e como ela aparece na atuação da ANPD?", pts:["Modelo de Ayres e Braithwaite: pirâmide que escala da persuasão à sanção.","Atividades de monitoramento, orientação, prevenção e repressão (Res. CD/ANPD 1/2021).","Sanção como último recurso, conforme a resposta do regulado.","Uso eficiente de recursos e foco em temas prioritários."]},
 {q:"Apresente três obrigações que o ECA Digital impõe a plataformas e explique o papel da ANPD.", pts:["Verificação de idade confiável, vedada a autodeclaração como único meio.","Supervisão parental e contas de menores de 16 vinculadas a responsável.","Vedação de loot boxes e de perfilamento para publicidade.","ANPD regulamenta, fiscaliza e aplica sanções (Lei 15.211/2025; Lei 15.352/2026)."]},
 {q:"Explique a diferença entre anonimização e pseudonimização e a consequência jurídica de cada uma.", pts:["Anonimização: dado perde a possibilidade de associação ao titular, por meios razoáveis.","Dado anonimizado não é dado pessoal, salvo reversão possível (art. 12).","Pseudonimização: associação depende de informação adicional mantida separadamente (art. 13, §4º).","Dado pseudonimizado continua sendo dado pessoal."]},
 {q:"Quais características dão às agências reguladoras a chamada natureza especial e por que elas importam para a ANPD?", pts:["Ausência de tutela ou subordinação hierárquica (Lei 13.848/2019, art. 3º).","Autonomia funcional, decisória, administrativa e financeira.","Mandato fixo e estabilidade dos dirigentes.","Reduz risco de captura e de interferência política; ANPD tornou-se agência pela Lei 15.352/2026."]},
 {q:"Como conciliar a Lei de Acesso à Informação com a LGPD no setor público?", pts:["As leis são complementares; a LGPD não revogou a LAI.","Transparência é a regra; informação pessoal tem acesso restrito (LAI, art. 31).","Tratamento pelo Poder Público exige finalidade pública (LGPD, art. 23).","Solução prática: divulgar o necessário, com anonimização ou tarjamento quando cabível."]},
 {q:"Explique o direito à revisão de decisões automatizadas e o que a ANPD pode fazer se o controlador negar informações alegando segredo comercial.", pts:["Titular pode pedir revisão de decisões tomadas unicamente com base em tratamento automatizado (art. 20).","A lei não exige que a revisão seja feita por pessoa natural.","Controlador deve informar critérios e procedimentos, observados os segredos comercial e industrial (§1º).","Se negar, a ANPD pode realizar auditoria para verificar aspectos discriminatórios (§2º)."]},
 {q:"O que muda com a decisão de adequação da União Europeia para as transferências internacionais de dados?", pts:["Res. CD/ANPD 32/2026 reconheceu a UE como destino com proteção adequada.","Transferências passam a se apoiar no art. 33, I, sem necessidade de cláusulas específicas.","Outros mecanismos (cláusulas-padrão, normas corporativas) continuam válidos.","Decisão é monitorada e reavaliada em 4 anos."]}
];

